assert.equal(GROWTH_SLICES[0].short, "US");
assert.equal(US_QUEUE_TECH[0].id, "solar");
assert.ok(VINTAGE_DELTAS.some((d) => d.id === "top1" && d.delta === 0));
assert.ok(VINTAGE_DELTAS.some((d) => d.id === "gasQueue" && d.direction === "up"));

