"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  CLEAN_INV_SHARES,
  COAL_ADD_SHARES,
  CONCENTRATION_CURVE,
  DEMAND_PATH,
  ELEC_DEMAND_LADDER,
  FUEL_EXPORT_STACK,
  GROWTH_ADD_SHARES,
  GROWTH_CONCENTRATION_CURVE,
  HEADLINE,
  HHI_BANDS,
  IMPORT_EXPOSURE,
  LENS_LABELS,
  MIX_PATH,
  SOLAR_ADD_SHARES,
  SOURCE_NOTE,
  VINTAGE_DELTAS,
  VINTAGE_SLOPE,
  filterRows,
  fmtHhi,
  fmtPct,
  fmtPp,
  hhiBand,
  lensExposures,
  sortedByMetric,
  type Lens,
} from "@/data/energy-systems-concentration-202608-data";

// viz-types: vintage delta bars, Top-k ladder bars, Lorenz area+line (stock+growth), demand path line, coal/solar add pies+bars, mix path multi-line, fuel export stacks, import??wholesale scatter, clean-inv pie, vintage multi-line, lens avg bars | layout: default

type ViewId = "scoreboard" | "curves" | "paths" | "trade" | "capex";
type Metric = "top1" | "top3" | "hhi" | "delta";
type CurveLens = "stock" | "growth";
type PathPanel = "demand" | "coal" | "solar" | "mix";

const ROSE = "#f43f5e";
const AMBER = "#f59e0b";
const SKY = "#0ea5e9";
const TEAL = "#14b8a6";
const VIOLET = "#8b5cf6";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

